import { createClient } from "npm:@supabase/supabase-js@2";

const SUPABASE_URL =
  Deno.env.get("SUPABASE_URL") ?? "";

const SERVICE_ROLE_KEY =
  Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";

const RESET_PEPPER =
  Deno.env.get("PASSWORD_RESET_PEPPER") ?? "";

const db = createClient(
  SUPABASE_URL,
  SERVICE_ROLE_KEY,
  {
    auth: {
      autoRefreshToken: false,
      persistSession: false,
    },
  }
);

const HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, apikey, content-type, x-client-info",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Content-Type": "application/json; charset=utf-8",
  "Cache-Control": "no-store",
};

type Body = Record<string, unknown>;

type Profile = {
  user_id: string;
  account_status: string;
};

type ResetRecord = {
  id: string;
  user_id: string;
  status: string;
};

function respond(
  value: Record<string, unknown>,
  status = 200
): Response {
  return new Response(JSON.stringify(value), {
    status,
    headers: HEADERS,
  });
}

function normalizePhone(value: unknown): string {
  const digits = String(value ?? "").replace(/\D/g, "");

  return digits.startsWith("62")
    ? `0${digits.slice(2)}`
    : digits;
}

function normalizeCode(value: unknown): string {
  return String(value ?? "")
    .trim()
    .toLowerCase();
}

function validPhone(value: string): boolean {
  return /^08[0-9]{8,11}$/.test(value);
}

function validCode(value: string): boolean {
  return /^[a-z]{4}$/.test(value);
}

function validPassword(
  value: unknown
): value is string {
  return (
    typeof value === "string" &&
    value.length >= 10 &&
    value.length <= 72
  );
}

function validUuid(value: unknown): value is string {
  return (
    typeof value === "string" &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      value
    )
  );
}

async function sha256(value: string): Promise<string> {
  const encoded = new TextEncoder().encode(value);

  const digest = await crypto.subtle.digest(
    "SHA-256",
    encoded
  );

  return Array.from(new Uint8Array(digest))
    .map((byte) =>
      byte.toString(16).padStart(2, "0")
    )
    .join("");
}

async function hashCode(
  requestId: string,
  userId: string,
  code: string
): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(RESET_PEPPER),
    {
      name: "HMAC",
      hash: "SHA-256",
    },
    false,
    ["sign"]
  );

  const text = `${requestId}:${userId}:${code}`;

  const signature = await crypto.subtle.sign(
    "HMAC",
    key,
    new TextEncoder().encode(text)
  );

  return Array.from(new Uint8Array(signature))
    .map((byte) =>
      byte.toString(16).padStart(2, "0")
    )
    .join("");
}

function generateCode(): string {
  let code = "";

  while (code.length < 4) {
    const bytes = crypto.getRandomValues(
      new Uint8Array(8)
    );

    for (const byte of bytes) {
      if (byte >= 234) continue;

      code += String.fromCharCode(
        97 + (byte % 26)
      );

      if (code.length === 4) break;
    }
  }

  return code;
}

function getClientIp(request: Request): string {
  const forwarded =
    request.headers.get("x-forwarded-for") ?? "";

  return (
    forwarded.split(",")[0].trim().slice(0, 100) ||
    request.headers.get("cf-connecting-ip") ||
    "unknown"
  );
}

async function rateLimit(key: string): Promise<boolean> {
  const hashed = await sha256(key);

  const { data, error } = await db.rpc(
    "check_login_rate_limit",
    {
      p_key: hashed,
    }
  );

  if (error) {
    console.error(
      "Pembatasan percobaan gagal:",
      error.message
    );

    return false;
  }

  return data === true;
}

async function checkLimits(
  request: Request,
  action: string,
  phone: string
): Promise<boolean> {
  const ipAllowed = await rateLimit(
    `password-recovery:${action}:ip:${getClientIp(request)}`
  );

  const phoneAllowed = await rateLimit(
    `password-recovery:${action}:phone:${phone}`
  );

  return ipAllowed && phoneAllowed;
}

async function findAccount(
  phone: string
): Promise<Profile | null> {
  const { data, error } = await db
    .from("profiles")
    .select("user_id, account_status")
    .eq("phone", phone)
    .maybeSingle();

  if (error) throw error;

  return data;
}

async function isAdmin(
  userId: string
): Promise<boolean> {
  const [roleResult, profileResult] =
    await Promise.all([
      db
        .from("user_roles")
        .select("role")
        .eq("user_id", userId)
        .eq("role", "admin")
        .maybeSingle(),

      db
        .from("profiles")
        .select("account_status")
        .eq("user_id", userId)
        .maybeSingle(),
    ]);

  if (
    roleResult.error ||
    profileResult.error
  ) {
    throw new Error(
      "Gagal memeriksa hak akses."
    );
  }

  return (
    Boolean(roleResult.data) &&
    profileResult.data?.account_status === "active"
  );
}

async function getAdminId(
  request: Request
): Promise<string | null> {
  const authorization =
    request.headers.get("authorization") ?? "";

  if (!authorization.startsWith("Bearer ")) {
    return null;
  }

  const token = authorization.slice(7).trim();

  if (!token) return null;

  const { data, error } =
    await db.auth.getUser(token);

  if (error || !data.user) {
    return null;
  }

  return (await isAdmin(data.user.id))
    ? data.user.id
    : null;
}

async function requestReset(
  request: Request,
  body: Body
): Promise<Response> {
  const phone = normalizePhone(body.phone);

  if (!validPhone(phone)) {
    return respond(
      { error: "Nomor HP tidak valid." },
      400
    );
  }

  if (
    !(await checkLimits(
      request,
      "request",
      phone
    ))
  ) {
    return respond(
      {
        error:
          "Terlalu banyak permintaan. Coba lagi dalam 15 menit.",
      },
      429
    );
  }

  const genericResult = {
    success: true,
    message:
      "Jika akun terdaftar, permintaan telah diterima.",
  };

  const account = await findAccount(phone);

  if (
    !account ||
    account.account_status !== "active" ||
    (await isAdmin(account.user_id))
  ) {
    return respond(genericResult);
  }

  const { data: existing, error: readError } =
    await db
      .from("password_reset_requests")
      .select("id")
      .eq("user_id", account.user_id)
      .in(
        "status",
        ["pending", "approved", "processing"]
      )
      .maybeSingle();

  if (readError) throw readError;

  if (existing) {
    return respond(genericResult);
  }

  const { error: insertError } = await db
    .from("password_reset_requests")
    .insert({
      user_id: account.user_id,
      status: "pending",
    });

  if (
    insertError &&
    insertError.code !== "23505"
  ) {
    throw insertError;
  }

  return respond(genericResult);
}

async function reviewReset(
  request: Request,
  body: Body
): Promise<Response> {
  const adminId = await getAdminId(request);

  if (!adminId) {
    return respond(
      { error: "Akses admin diperlukan." },
      403
    );
  }

  const requestId = body.request_id;
  const decision = String(body.decision ?? "");

  if (
    !validUuid(requestId) ||
    !["approve", "reject", "revoke"].includes(
      decision
    )
  ) {
    return respond(
      { error: "Data keputusan tidak valid." },
      400
    );
  }

  const { data: record, error: readError } =
    await db
      .from("password_reset_requests")
      .select("id, user_id, status")
      .eq("id", requestId)
      .maybeSingle();

  if (readError) throw readError;

  if (!record) {
    return respond(
      { error: "Permintaan tidak ditemukan." },
      404
    );
  }

  if (record.user_id === adminId) {
    return respond(
      {
        error:
          "Admin tidak boleh memulihkan akunnya sendiri.",
      },
      403
    );
  }

  if (
    decision === "reject" ||
    decision === "revoke"
  ) {
    const requiredStatus =
      decision === "reject"
        ? "pending"
        : "approved";

    const newStatus =
      decision === "reject"
        ? "rejected"
        : "revoked";

    if (record.status !== requiredStatus) {
      return respond(
        {
          error:
            "Permintaan sudah diproses atau sedang digunakan.",
        },
        409
      );
    }

    const fields =
      decision === "reject"
        ? {
            status: newStatus,
            reviewed_by: adminId,
            reviewed_at:
              new Date().toISOString(),
          }
        : {
            status: newStatus,
            revoked_at:
              new Date().toISOString(),
            lock_reason:
              "Dicabut oleh admin",
          };

    const { data, error } = await db
      .from("password_reset_requests")
      .update(fields)
      .eq("id", requestId)
      .eq("status", requiredStatus)
      .select("id")
      .maybeSingle();

    if (error) throw error;

    if (!data) {
      return respond(
        {
          error:
            "Permintaan telah diproses oleh pihak lain.",
        },
        409
      );
    }

    return respond({
      success: true,
      message:
        decision === "reject"
          ? "Permintaan ditolak."
          : "Kode pemulihan dicabut.",
    });
  }

  if (record.status !== "pending") {
    return respond(
      {
        error:
          "Permintaan tidak lagi menunggu persetujuan.",
      },
      409
    );
  }

  const code = generateCode();

  const code_hash = await hashCode(
    record.id,
    record.user_id,
    code
  );

  const { data: approved, error } =
    await db
      .from("password_reset_requests")
      .update({
        status: "approved",
        code_hash,
        code_attempts: 0,
        reviewed_by: adminId,
        reviewed_at:
          new Date().toISOString(),
      })
      .eq("id", requestId)
      .eq("status", "pending")
      .select("id")
      .maybeSingle();

  if (error) throw error;

  if (!approved) {
    return respond(
      {
        error:
          "Permintaan sudah diproses oleh admin lain.",
      },
      409
    );
  }

  return respond({
    success: true,
    code,
    message:
      "Permintaan disetujui. Salin kode sekarang.",
  });
}

async function redeemReset(
  request: Request,
  body: Body
): Promise<Response> {
  const phone = normalizePhone(body.phone);
  const code = normalizeCode(body.code);
  const password = body.password;

  if (!validPhone(phone)) {
    return respond(
      { error: "Nomor HP tidak valid." },
      400
    );
  }

  if (!validCode(code)) {
    return respond(
      { error: "Kode harus terdiri dari 4 huruf." },
      400
    );
  }

  if (!validPassword(password)) {
    return respond(
      {
        error:
          "Kata sandi harus terdiri dari 10–72 karakter.",
      },
      400
    );
  }

  if (
    !(await checkLimits(
      request,
      "redeem",
      phone
    ))
  ) {
    return respond(
      {
        error:
          "Terlalu banyak percobaan. Coba lagi dalam 15 menit.",
      },
      429
    );
  }

  const account = await findAccount(phone);

  if (
    !account ||
    account.account_status !== "active" ||
    (await isAdmin(account.user_id))
  ) {
    return respond(
      {
        error:
          "Kode pemulihan tidak valid atau tidak aktif.",
      },
      400
    );
  }

  const { data: record, error: readError } =
    await db
      .from("password_reset_requests")
      .select("id, user_id, status")
      .eq("user_id", account.user_id)
      .eq("status", "approved")
      .maybeSingle();

  if (readError) throw readError;

  if (!record) {
    return respond(
      {
        error:
          "Kode pemulihan tidak valid atau sedang diproses.",
      },
      400
    );
  }

  const providedHash = await hashCode(
    record.id,
    record.user_id,
    code
  );

  const processingId = crypto.randomUUID();

  // RPC mengunci baris database secara atomik.
  // Hanya satu permintaan yang boleh
  // memperoleh status processing.
  const { data: claimResult, error: claimError } =
    await db.rpc(
      "claim_password_reset_code",
      {
        p_request_id: record.id,
        p_user_id: account.user_id,
        p_code_hash: providedHash,
        p_processing_id: processingId,
      }
    );

  if (claimError) {
    throw claimError;
  }

  if (claimResult !== "claimed") {
    return respond(
      {
        error:
          claimResult === "revoked"
            ? "Kode dibatalkan karena terlalu banyak percobaan salah. Hubungi admin."
            : "Kode tidak valid atau sedang diproses.",
      },
      claimResult === "revoked" ? 403 : 400
    );
  }

  // Setelah claim berhasil, permintaan lain
  // tidak bisa mengambil kode yang sama.
  let passwordUpdated = false;

  try {
    const { error: updateError } =
      await db.auth.admin.updateUserById(
        account.user_id,
        {
          password,
        }
      );

    if (updateError) {
      throw updateError;
    }

    passwordUpdated = true;
  } catch (authError) {
    console.error(
      "Pembaruan Auth gagal:",
      authError
    );
  }

  const { data: finished, error: finishError } =
    await db.rpc(
      "finish_password_reset_code",
      {
        p_request_id: record.id,
        p_processing_id: processingId,
        p_success: passwordUpdated,
      }
    );

  if (finishError || finished !== true) {
    console.error(
      "Finalisasi pemulihan gagal:",
      finishError?.message
    );

    return respond(
      {
        error: passwordUpdated
          ? "Kata sandi mungkin sudah diperbarui, tetapi pencatatan belum selesai. Coba login dengan kata sandi baru dan hubungi admin bila perlu."
          : "Pemulihan belum selesai. Hubungi admin sekolah.",
      },
      500
    );
  }

  if (!passwordUpdated) {
    return respond(
      {
        error:
          "Gagal memperbarui kata sandi. Kode tetap aktif; silakan coba kembali.",
      },
      500
    );
  }

  return respond({
    success: true,
    message:
      "Kata sandi berhasil diperbarui. Silakan masuk kembali.",
  });
}

Deno.serve(
  async (request: Request): Promise<Response> => {
    if (request.method === "OPTIONS") {
      return respond({});
    }

    if (request.method !== "POST") {
      return respond(
        { error: "Metode tidak diizinkan." },
        405
      );
    }

    try {
      if (
        !SUPABASE_URL ||
        !SERVICE_ROLE_KEY ||
        RESET_PEPPER.length < 32
      ) {
        console.error(
          "Konfigurasi password-recovery tidak lengkap."
        );

        return respond(
          {
            error:
              "Konfigurasi server belum lengkap.",
          },
          500
        );
      }

      let body: Body;

      try {
        const parsed = await request.json();

        if (
          !parsed ||
          typeof parsed !== "object" ||
          Array.isArray(parsed)
        ) {
          return respond(
            { error: "Data tidak valid." },
            400
          );
        }

        body = parsed;
      } catch {
        return respond(
          { error: "Data tidak valid." },
          400
        );
      }

      const action = String(
        body.action ?? ""
      );

      if (action === "request") {
        return await requestReset(
          request,
          body
        );
      }

      if (action === "review") {
        return await reviewReset(
          request,
          body
        );
      }

      if (action === "redeem") {
        return await redeemReset(
          request,
          body
        );
      }

      return respond(
        {
          error:
            "Tindakan tidak dikenal.",
        },
        400
      );
    } catch (error) {
      console.error(
        "password-recovery:",
        error
      );

      return respond(
        {
          error:
            "Terjadi gangguan server.",
        },
        500
      );
    }
  }
);

import { createClient } from "npm:@supabase/supabase-js@2";
const URL = Deno.env.get("SUPABASE_URL") ?? "";
const KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "";
const PEPPER = Deno.env.get("PASSWORD_RESET_PEPPER") ?? "";
const db=createClient(URL,KEY,{auth:{persistSession:false,autoRefreshToken:false}});
const headers={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"authorization,apikey,content-type,x-client-info","Access-Control-Allow-Methods":"POST,OPTIONS","Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"};
const result=(value:Record<string,unknown>,status=200)=>new Response(JSON.stringify(value),{status,headers});
const uuid=(v:unknown):v is string=>typeof v==="string"&&/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);
async function getAdmin(req:Request){
 const a=req.headers.get("authorization")??"";if(!a.startsWith("Bearer "))return null;
 const {data,error}=await db.auth.getUser(a.slice(7));if(error||!data.user)return null;
 const id=data.user.id;
 const [role,profile]=await Promise.all([db.from("user_roles").select("role").eq("user_id",id).eq("role","admin").maybeSingle(),db.from("profiles").select("account_status").eq("user_id",id).maybeSingle()]);
 return !role.error&&!profile.error&&role.data&&profile.data?.account_status==="active"?id:null;
}
async function hmac(id:string,user:string,code:string){
 const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(PEPPER),{name:"HMAC",hash:"SHA-256"},false,["sign"]);
 const signature=await crypto.subtle.sign("HMAC",key,new TextEncoder().encode(`${id}:${user}:${code}`));
 return Array.from(new Uint8Array(signature)).map(b=>b.toString(16).padStart(2,"0")).join("");
}
function newCode(){
 let code="";while(code.length<4){const bytes=crypto.getRandomValues(new Uint8Array(8));for(const b of bytes){if(b>=234)continue;code+=String.fromCharCode(97+(b%26));if(code.length===4)break;}}return code;
}
Deno.serve(async req=>{
 if(req.method==="OPTIONS")return result({});
 if(req.method!=="POST")return result({error:"Metode tidak diizinkan."},405);
 try{
  if(!URL||!KEY||PEPPER.length<32)return result({error:"Konfigurasi server belum lengkap."},500);
  const admin=await getAdmin(req);if(!admin)return result({error:"Akses admin diperlukan."},403);
  let body:Record<string,unknown>;
  try{const parsed=await req.json();if(!parsed||typeof parsed!=="object"||Array.isArray(parsed))throw new Error("format");body=parsed;}catch{return result({error:"Format permintaan tidak valid."},400);}
  if(!uuid(body.request_id))return result({error:"ID permintaan tidak valid."},400);
  const {data:record,error:readError}=await db.from("password_reset_requests").select("id,user_id,status,code_hash,processing_started_at").eq("id",body.request_id).maybeSingle();
  if(readError)throw readError;
  if(!record)return result({error:"Permintaan tidak ditemukan."},404);
  if(record.user_id===admin)return result({error:"Tidak dapat memproses akun admin sendiri."},403);
  if(body.action==="reissue"){
   if(record.status!=="approved")return result({error:"Hanya kode berstatus disetujui yang dapat diterbitkan ulang."},409);
   let code="",hash="";
   for(let i=0;i<10;i++){const candidate=newCode();const candidateHash=await hmac(record.id,record.user_id,candidate);if(candidateHash!==record.code_hash){code=candidate;hash=candidateHash;break;}}
   if(!code)return result({error:"Gagal membuat kode baru."},500);
   const {data,error}=await db.rpc("rotate_approved_password_reset_code",{p_request_id:record.id,p_admin_id:admin,p_code_hash:hash});
   if(error)throw error;
   if(data!==true)return result({error:"Status berubah. Muat ulang notifikasi."},409);
   return result({success:true,code,message:"Kode baru diterbitkan. Kode lama tidak berlaku."});
  }
  if(body.action==="cancel_stuck"){
   if(record.status!=="processing")return result({error:"Permintaan tidak sedang diproses."},409);
   const t=new Date(record.processing_started_at).getTime();
   if(!Number.isFinite(t)||Date.now()-t<300000)return result({error:"Proses belum melewati lima menit."},409);
   const {data,error}=await db.rpc("cancel_stuck_password_reset",{p_request_id:record.id,p_admin_id:admin});
   if(error)throw error;
   if(data!==true)return result({error:"Status berubah atau belum memenuhi syarat."},409);
   return result({success:true,message:"Proses ditutup. Periksa akses akun pengguna."});
  }
  return result({error:"Tindakan tidak dikenal."},400);
 }catch(e){console.error("recovery-admin",e);return result({error:"Gangguan server."},500);}
});
